import{_ as t,o as n,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Was ist eine Ansicht","description":"Ansichten in ApptiveGrid verstehen — sieben Ansichtstypen auf denselben Daten.","frontmatter":{"title":"Was ist eine Ansicht","description":"Ansichten in ApptiveGrid verstehen — sieben Ansichtstypen auf denselben Daten."},"headers":[],"relativePath":"ansichten/was-ist-eine-ansicht.md","filePath":"ansichten/was-ist-eine-ansicht.md","lastUpdated":1786092153000}'),r={name:"ansichten/was-ist-eine-ansicht.md"};function s(l,e,d,h,o,c){return n(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="was-ist-eine-ansicht" tabindex="-1">Was ist eine Ansicht <a class="header-anchor" href="#was-ist-eine-ansicht" aria-label="Permalink to &quot;Was ist eine Ansicht&quot;">​</a></h1><p>Eine <strong>Ansicht</strong> ist eine bestimmte Darstellung eines Grids. Sie legt fest, welche Einträge sichtbar sind, in welcher Reihenfolge sie stehen, wie sie gebündelt werden und welche Spalten erscheinen.</p><p><strong>Eine Ansicht verändert die Daten nicht.</strong> Sie ist eine Brille auf dasselbe Grid.</p><h2 id="warum-das-wichtig-ist" tabindex="-1">Warum das wichtig ist <a class="header-anchor" href="#warum-das-wichtig-ist" aria-label="Permalink to &quot;Warum das wichtig ist&quot;">​</a></h2><p>Dies ist die häufigste Verständnishürde bei ApptiveGrid. Machen Sie sich den Unterschied früh klar:</p><table tabindex="0"><thead><tr><th></th><th>Grid</th><th>Ansicht</th></tr></thead><tbody><tr><td>Enthält</td><td>die Daten</td><td>nur Anzeigeregeln</td></tr><tr><td>Beim Löschen</td><td>Daten sind weg</td><td>Daten bleiben erhalten</td></tr><tr><td>Anzahl</td><td>eines je Datenbestand</td><td>beliebig viele je Grid</td></tr></tbody></table><p>Ein Grid „Aufgaben&quot; kann gleichzeitig haben:</p><ul><li>eine Tabelle mit allen Aufgaben,</li><li>eine gefilterte Tabelle nur mit offenen Aufgaben,</li><li>ein Kanban-Board nach Status,</li><li>einen Kalender nach Fälligkeitsdatum.</li></ul><p>Vier Ansichten, ein Datenbestand. Ändert jemand eine Aufgabe im Kanban-Board, ist die Änderung sofort in allen anderen Ansichten sichtbar.</p><div class="danger custom-block"><p class="custom-block-title">Ansicht löschen betrifft Formulare</p><p>Formulare und geteilte Links hängen an einer Ansicht. Beim Löschen warnt ApptiveGrid mit dem Hinweis, dass Ihre erstellten Formulare nach dem Löschen nicht mehr funktionieren.</p><p>Prüfen Sie vor dem Löschen, ob an dieser Ansicht Formulare oder geteilte Links hängen. Der Datenbestand bleibt erhalten, aber ein extern verteilter Formularlink wird ungültig.</p></div><h2 id="die-sieben-ansichtstypen" tabindex="-1">Die sieben Ansichtstypen <a class="header-anchor" href="#die-sieben-ansichtstypen" aria-label="Permalink to &quot;Die sieben Ansichtstypen&quot;">​</a></h2><h3 id="grid-ansicht" tabindex="-1">Grid-Ansicht <a class="header-anchor" href="#grid-ansicht" aria-label="Permalink to &quot;Grid-Ansicht&quot;">​</a></h3><p>Die klassische Tabelle: Zeilen sind Einträge, Spalten sind Felder. Der Standard und der Ausgangspunkt für alles Weitere.</p><p>Geeignet für: Datenpflege, Massenbearbeitung, vollständige Übersicht.</p><h3 id="kanban" tabindex="-1">Kanban <a class="header-anchor" href="#kanban" aria-label="Permalink to &quot;Kanban&quot;">​</a></h3><p>Karten in Spalten, die sich per Drag &amp; Drop verschieben lassen. Die Spalten entstehen aus einem Feld vom Typ <strong>Einzelauswahl</strong> — meist ein Statusfeld.</p><p>Welche Angaben auf einer Karte erscheinen, konfigurieren Sie je Ansicht.</p><p>Geeignet für: Arbeitsabläufe mit klaren Stufen wie Bewerbungen, Tickets, Vertriebschancen.</p><p>→ <a href="/ansichten/kanban">Kanban</a></p><h3 id="kalender" tabindex="-1">Kalender <a class="header-anchor" href="#kalender" aria-label="Permalink to &quot;Kalender&quot;">​</a></h3><p>Einträge auf einem Kalenderblatt, positioniert über ein Datumsfeld.</p><p>Geeignet für: Termine, Fristen, Belegungen.</p><p>→ <a href="/ansichten/kalender">Kalender</a></p><h3 id="karte" tabindex="-1">Karte <a class="header-anchor" href="#karte" aria-label="Permalink to &quot;Karte&quot;">​</a></h3><p>Einträge als Markierungen auf einer Landkarte, positioniert über ein Feld vom Typ <strong>Adresse</strong> oder <strong>Geolokalisierung</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Voraussetzung für Adressen</p><p>Damit eine Adresse als Kartenmarkierung erscheint, müssen Koordinaten dazu ermittelt werden. Diese Geokodierung ist tarifabhängig. Bei Feldern vom Typ <em>Geolokalisierung</em> mit direkt eingetragenen Koordinaten entfällt diese Einschränkung.</p></div><p>→ <a href="/ansichten/karte">Karte</a></p><h3 id="galerie" tabindex="-1">Galerie <a class="header-anchor" href="#galerie" aria-label="Permalink to &quot;Galerie&quot;">​</a></h3><p>Einträge als Karten mit Bildern. Das Layout der Karten ist konfigurierbar.</p><p>Geeignet für: Produktkataloge, Personenverzeichnisse, alles Bildlastige.</p><p>→ <a href="/ansichten/galerie">Galerie</a></p><h3 id="liste" tabindex="-1">Liste <a class="header-anchor" href="#liste" aria-label="Permalink to &quot;Liste&quot;">​</a></h3><p>Eine kompakte, untereinander stehende Darstellung — platzsparender als die Tabelle und besonders auf schmalen Bildschirmen gut lesbar.</p><p>→ <a href="/ansichten/liste">Liste</a></p><h3 id="timeline" tabindex="-1">Timeline <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;Timeline&quot;">​</a></h3><p>Einträge auf einem Zeitstrahl, in den Rastern <em>Tag</em>, <em>Woche</em>, <em>Monat</em> und <em>Jahr</em>. Geeignet für Projektplanung und Belegungspläne.</p><div class="warning custom-block"><p class="custom-block-title">Zwei Voraussetzungen</p><ol><li><strong>Ein Feld vom Typ <em>Mehrere Einträge verknüpfen</em>.</strong> Ohne das meldet ApptiveGrid: <em>Um eine Timeline zu sehen, muss Ihr Grid eine Spalte vom Typ Mehrfachreferenz besitzen.</em> Dieses Referenzfeld bestimmt die Zeilen des Zeitstrahls.</li><li><strong>Datumsfelder im verknüpften Grid</strong> für Start und Ende. Fehlen sie, meldet ApptiveGrid: <em>Das referenzierte Grid hat keine Datums- oder Datumszeitfelder.</em></li></ol><p>Die Timeline ist damit die einzige Ansicht, die über zwei Grids hinweg konfiguriert wird.</p><p>Zusätzlich ist sie tarifabhängig.</p></div><p>→ <a href="/ansichten/timeline">Timeline</a></p><h2 id="ansicht-anlegen" tabindex="-1">Ansicht anlegen <a class="header-anchor" href="#ansicht-anlegen" aria-label="Permalink to &quot;Ansicht anlegen&quot;">​</a></h2><ol><li>Wählen Sie in der Seitenleiste unter dem Grid den Bereich <strong>Ansichten</strong>.</li><li>Klicken Sie auf <strong>Ansicht erstellen</strong>.</li><li>Wählen Sie den Ansichtstyp.</li><li>Vergeben Sie einen Namen.</li></ol><div class="tip custom-block"><p class="custom-block-title">Duplizieren spart Arbeit</p><p>Über <em>Weitere</em> (⋮) → <strong>Duplizieren</strong> erzeugen Sie eine Kopie mit allen Filtern, Sortierungen und Spalteneinstellungen. Schneller, als eine ähnliche Ansicht neu aufzubauen.</p></div><h2 id="was-zur-ansicht-gehort-und-was-zum-grid" tabindex="-1">Was zur Ansicht gehört und was zum Grid <a class="header-anchor" href="#was-zur-ansicht-gehort-und-was-zum-grid" aria-label="Permalink to &quot;Was zur Ansicht gehört und was zum Grid&quot;">​</a></h2><p>Diese Unterscheidung erspart viel Verwirrung im Team:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Gilt für</th></tr></thead><tbody><tr><td>Filter</td><td><strong>nur diese Ansicht</strong></td></tr><tr><td>Sortierung</td><td><strong>nur diese Ansicht</strong></td></tr><tr><td>Gruppierung</td><td><strong>nur diese Ansicht</strong></td></tr><tr><td>Ausgeblendete Spalten</td><td><strong>nur diese Ansicht</strong></td></tr><tr><td>Spaltenreihenfolge</td><td><strong>nur diese Ansicht</strong></td></tr><tr><td>Gesperrte Spalten</td><td><strong>nur diese Ansicht</strong></td></tr><tr><td>Leerzustand-Text</td><td><strong>nur diese Ansicht</strong></td></tr><tr><td>Feldname</td><td><strong>das ganze Grid</strong></td></tr><tr><td>Spaltentyp</td><td><strong>das ganze Grid</strong></td></tr><tr><td>Auswahloptionen</td><td><strong>das ganze Grid</strong></td></tr><tr><td>Einträge und Werte</td><td><strong>das ganze Grid</strong></td></tr></tbody></table><p>Kurz: Alles, was mit <em>Darstellung</em> zu tun hat, gehört zur Ansicht. Alles, was mit <em>Struktur und Inhalt</em> zu tun hat, gehört zum Grid.</p><p>Ändern Sie also den Namen einer Spalte, ändert er sich überall. Blenden Sie eine Spalte aus, betrifft das nur Ihre Ansicht.</p><h2 id="ansicht-teilen" tabindex="-1">Ansicht teilen <a class="header-anchor" href="#ansicht-teilen" aria-label="Permalink to &quot;Ansicht teilen&quot;">​</a></h2><p>Jede Ansicht lässt sich als privater Link teilen. Empfänger sehen nur die Daten, die in dieser Ansicht sichtbar sind — Filter und ausgeblendete Spalten wirken also auch als Sichtschutz.</p><div class="warning custom-block"><p class="custom-block-title">Filter sind kein vollwertiger Zugriffsschutz</p><p>Verlassen Sie sich bei wirklich sensiblen Daten nicht allein darauf, sie in einer geteilten Ansicht auszublenden. Setzen Sie zusätzlich eine <a href="/zusammenarbeit/zugriff-beschraenken">Zugriffsbeschränkung</a> auf den Link.</p></div><p>→ <a href="/ansichten/ansicht-teilen">Ansicht teilen</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></li><li><a href="/ansichten/spalten-verwalten">Spalten verwalten</a></li><li><a href="/ansichten/ansicht-teilen">Ansicht teilen</a></li></ul>',52)])])}const p=t(r,[["render",s]]);export{g as __pageData,p as default};
